"use client";

import { DiffReview, type DiffReviewProps } from "@/components/agents/diff-review";

/**
 * Pass host-owned file versions and real persistence callbacks.
 * onDecision and onComment may reject: the UI retains its previous state and
 * displays the error. onCommit receives only the selected version of each file,
 * with accepted/rejected hunk IDs; apply those IDs in your repository service.
 * For controlled decisions persist keys generated by reviewDecisionKey().
 */
export function DiffReviewUsage({ files, onDecision, onComment, onCommit }: Pick<DiffReviewProps, "files" | "onDecision" | "onComment" | "onCommit">) {
  return <DiffReview files={files} onDecision={onDecision} onComment={onComment} onCommit={onCommit} />;
}
